"use strict";

/**
 * Temperature Converter
 * Converts a list of sample temperatures between Celsius, Fahrenheit and Kelvin,
 * then prints a tidy conversion table.
 */

// --- Conversion helpers ---------------------------------------------------

function celsiusToFahrenheit(c) {
  return (c * 9) / 5 + 32;
}

function celsiusToKelvin(c) {
  return c + 273.15;
}

// Round to 1 decimal place so the table stays readable.
function round1(n) {
  return Math.round(n * 10) / 10;
}

// Pad a value on the right so columns line up nicely.
function pad(text, width) {
  text = String(text);
  while (text.length < width) text += " ";
  return text;
}

// --- Sample data ----------------------------------------------------------

// A few familiar temperatures (in Celsius) students can relate to.
const samples = [
  { label: "Water freezes", c: 0 },
  { label: "Cold day", c: 10 },
  { label: "Room temp", c: 22 },
  { label: "Body temp", c: 37 },
  { label: "Hot day", c: 40 },
  { label: "Water boils", c: 100 },
];

// --- Build and print the table --------------------------------------------

console.log("Temperature Conversion Table");
console.log("============================");
console.log(pad("Description", 16) + pad("Celsius", 10) + pad("Fahrenheit", 12) + "Kelvin");
console.log("-".repeat(48));

for (const item of samples) {
  const f = round1(celsiusToFahrenheit(item.c));
  const k = round1(celsiusToKelvin(item.c));
  console.log(
    pad(item.label, 16) +
      pad(item.c + " C", 10) +
      pad(f + " F", 12) +
      k + " K"
  );
}

console.log("-".repeat(48));
console.log("Tip: F = C x 9/5 + 32, and K = C + 273.15");

"use strict";

/**
 * Number-Guessing Game (auto-play demo)
 * Shows how a binary-search strategy quickly finds a secret number,
 * printing each guess and whether it was too high, too low, or correct.
 */

// The "secret" number the computer must find (1..100).
const secret = 73;

// Search range the player knows about.
let low = 1;
let high = 100;
let attempts = 0;

console.log("Number-Guessing Game (computer plays itself)");
console.log("Secret number is between 1 and 100.");
console.log("Strategy: always guess the middle of the remaining range.\n");

while (low <= high) {
  attempts++;

  // The smartest guess is the midpoint of what's left.
  const guess = Math.floor((low + high) / 2);
  process.stdout.write("Attempt " + attempts + ": guessing " + guess + " -> ");

  if (guess === secret) {
    console.log("correct!");
    break;
  } else if (guess < secret) {
    console.log("too low");
    low = guess + 1; // secret must be higher
  } else {
    console.log("too high");
    high = guess - 1; // secret must be lower
  }
}

console.log("\nFound " + secret + " in " + attempts + " attempts.");
console.log("Because the range halves each time, it never needs more than 7 guesses for 1-100.");

"use strict";

/**
 * To-Do List Manager
 * A tiny in-memory task list showing add, complete, and report operations.
 * Demonstrates objects, arrays, and array methods (filter, map, forEach).
 */

// Each task is an object with an id, text, and done flag.
const tasks = [];
let nextId = 1;

// Add a new task to the list.
function addTask(text) {
  tasks.push({ id: nextId++, text: text, done: false });
}

// Mark a task as completed by its id.
function completeTask(id) {
  const task = tasks.find((t) => t.id === id);
  if (task) task.done = true;
}

// Print the whole list with checkboxes.
function showList() {
  console.log("My To-Do List");
  console.log("=============");
  tasks.forEach((t) => {
    const box = t.done ? "[x]" : "[ ]";
    console.log(box + " " + t.id + ". " + t.text);
  });

  const doneCount = tasks.filter((t) => t.done).length;
  const remaining = tasks.length - doneCount;
  console.log("-------------");
  console.log("Completed: " + doneCount + "  Remaining: " + remaining);
}

// --- Demo run -------------------------------------------------------------

addTask("Finish maths homework");
addTask("Read one chapter of a book");
addTask("Practise coding for 20 minutes");
addTask("Tidy my room");

console.log("Starting list:\n");
showList();

// Complete a couple of tasks.
completeTask(1);
completeTask(3);

console.log("\nAfter finishing tasks 1 and 3:\n");
showList();

if (tasks.every((t) => t.done)) {
  console.log("\nAll done! Great work.");
} else {
  console.log("\nKeep going, you are making progress!");
}

/* ===== Page basics ===== */
* {
  box-sizing: border-box; /* padding/border counted inside width */
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  background: linear-gradient(135deg, #1e1b4b, #312e81);
  color: #f1f5f9;
  min-height: 100vh;
  padding: 2rem 1rem;
}

.page-header {
  text-align: center;
  margin-bottom: 2.5rem;
}

.page-header h1 {
  font-size: 2.2rem;
  margin-bottom: 0.5rem;
}

.page-header p {
  color: #c7d2fe;
}

/* ===== Responsive grid of cards ===== */
.gallery {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 1.5rem;
  max-width: 960px;
  margin: 0 auto;
}

.card {
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 16px;
  padding: 1.5rem;
  text-align: center;
  transition: transform 0.2s ease, background 0.2s ease;
}

.card:hover {
  transform: translateY(-4px);
  background: rgba(255, 255, 255, 0.1);
}

.card h2 {
  font-size: 1.15rem;
  margin-bottom: 0.4rem;
}

.card p {
  font-size: 0.85rem;
  color: #cbd5e1;
}

/* The fixed-height box that holds each animation */
.demo {
  height: 90px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1rem;
}

/* ===== 1. Rotating ring ===== */
.spinner-ring {
  width: 54px;
  height: 54px;
  border: 6px solid rgba(255, 255, 255, 0.2);
  border-top-color: #38bdf8; /* only the top edge is coloured */
  border-radius: 50%;
  animation: spin 1s linear infinite;
}

@keyframes spin {
  to { transform: rotate(360deg); }
}

/* ===== 2. Bouncing dots ===== */
.spinner-dots {
  display: flex;
  gap: 8px;
}

.spinner-dots span {
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: #f472b6;
  animation: bounce 0.6s ease-in-out infinite;
}

/* Stagger each dot so they bounce one after another */
.spinner-dots span:nth-child(2) { animation-delay: 0.15s; }
.spinner-dots span:nth-child(3) { animation-delay: 0.3s; }

@keyframes bounce {
  0%, 100% { transform: translateY(0); opacity: 0.6; }
  50%      { transform: translateY(-18px); opacity: 1; }
}

/* ===== 3. Pulse ===== */
.spinner-pulse {
  width: 54px;
  height: 54px;
  border-radius: 50%;
  background: #34d399;
  animation: pulse 1.2s ease-in-out infinite;
}

@keyframes pulse {
  0%   { transform: scale(0.4); opacity: 1; }
  100% { transform: scale(1.3); opacity: 0; }
}

/* ===== 4. Flipping square ===== */
.spinner-flip {
  width: 48px;
  height: 48px;
  background: #fbbf24;
  border-radius: 6px;
  animation: flip 1.4s ease-in-out infinite;
}

@keyframes flip {
  0%   { transform: rotateX(0)    rotateY(0); }
  50%  { transform: rotateX(180deg) rotateY(0); }
  100% { transform: rotateX(180deg) rotateY(180deg); }
}

/* ===== 5. Sound bars ===== */
.spinner-bars {
  display: flex;
  align-items: flex-end;
  gap: 5px;
  height: 50px;
}

.spinner-bars span {
  width: 7px;
  height: 100%;
  background: #a78bfa;
  border-radius: 4px;
  animation: equalise 1s ease-in-out infinite;
}

/* Different delays make the bars look random and lively */
.spinner-bars span:nth-child(1) { animation-delay: 0s;    }
.spinner-bars span:nth-child(2) { animation-delay: 0.2s;  }
.spinner-bars span:nth-child(3) { animation-delay: 0.4s;  }
.spinner-bars span:nth-child(4) { animation-delay: 0.15s; }
.spinner-bars span:nth-child(5) { animation-delay: 0.35s; }

@keyframes equalise {
  0%, 100% { transform: scaleY(0.3); }
  50%      { transform: scaleY(1); }
}

