// Temperature Converter
// Converts a list of temperatures between Celsius, Fahrenheit and Kelvin,
// then prints a tidy comparison table.

// --- Conversion helpers (pure functions, easy to test) ---
function celsiusToFahrenheit(c: number): number {
  return c * 9 / 5 + 32;
}

function celsiusToKelvin(c: number): number {
  return c + 273.15;
}

function fahrenheitToCelsius(f: number): number {
  return (f - 32) * 5 / 9;
}

// Round to 1 decimal place so the table stays readable.
function round1(n: number): number {
  return Math.round(n * 10) / 10;
}

// Pad a string on the right so columns line up.
function pad(text: string, width: number): string {
  return text.padEnd(width, " ");
}

// --- Sample data: a few everyday temperatures in Celsius ---
const samplesCelsius: number[] = [-40, 0, 20, 37, 100];

console.log("Temperature Converter");
console.log("=====================\n");

// Print the table header.
console.log(pad("Celsius", 10) + pad("Fahrenheit", 12) + "Kelvin");
console.log("-".repeat(28));

// Convert and print each sample.
