// Password Strength Generator
// Builds a few sample passwords from different character sets and rates
// how strong each one is. No user input needed.

// Character sets we can draw from.
const LOWER = "abcdefghijklmnopqrstuvwxyz";
const UPPER = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
const DIGITS = "0123456789";
const SYMBOLS = "!@#$%^&*?";

// Options that control which character sets a password uses.
interface PasswordOptions {
  length: number;
  useUpper: boolean;
  useDigits: boolean;
  useSymbols: boolean;
}

// Generate a password by picking random characters from the chosen pool.
function generatePassword(opts: PasswordOptions): string {
  let pool = LOWER;
  if (opts.useUpper) pool += UPPER;
  if (opts.useDigits) pool += DIGITS;
  if (opts.useSymbols) pool += SYMBOLS;

  let password = "";
  for (let i = 0; i < opts.length; i++) {
    const index = Math.floor(Math.random() * pool.length);
    password += pool[index];
  }
  return password;
}

// Rate a password as Weak, Okay or Strong based on simple rules.
function rateStrength(password: string): string {
  let score = 0;
  if (password.length >= 12) score++;
  if (/[A-Z]/.test(password)) score++;
  if (/[0-9]/.test(password)) score++;
  if (/[!@#$%^&*?]/.test(password)) score++;

  if (score <= 1) return "Weak";
  if (score === 2 || score === 3) return "Okay";
  return "Strong";
}

console.log("Password Generator");
console.log("==================\n");

// Three example configurations, from simple to secure.
const examples: { label: string; opts: PasswordOptions }[] = [
  { label: "Simple  ", opts: { length: 8, useUpper: false, useDigits: false, useSymbols: false } },
  { label: "Medium  ", opts: { length: 10, useUpper: true, useDigits: true, useSymbols: false } },
  { label: "Strong  ", opts: { length: 14, useUpper: true, useDigits: true, useSymbols: true } },
];

for (const example of examples) {
  const pwd = generatePassword(example.opts);
  const strength = rateStrength(pwd);
  console.log(`${example.label} -> ${pwd}   [${strength}]`);
}

console.log("\nTip: longer passwords with a mix of letters, numbers and symbols are hardest to guess.");

// Temperature Converter
// Converts temperatures between Celsius, Fahrenheit, and Kelvin.
// This program uses built-in sample data (no keyboard input needed)
// and prints a clean conversion table to the screen.
package main

import "fmt"

// celsiusToFahrenheit turns a Celsius value into Fahrenheit.
// Formula: F = C * 9/5 + 32
func celsiusToFahrenheit(c float64) float64 {
	return c*9.0/5.0 + 32.0
}

// celsiusToKelvin turns a Celsius value into Kelvin.
// Formula: K = C + 273.15
func celsiusToKelvin(c float64) float64 {
	return c + 273.15
}

// describe gives a friendly label for a Celsius temperature
// so the output is easier for students to understand.
func describe(c float64) string {
	switch {
	case c <= 0:
		return "freezing"
	case c < 15:
		return "cold"
	case c < 25:
		return "mild"
	case c < 35:
		return "warm"
	default:
		return "hot"
	}
}

func main() {
	// Sample Celsius temperatures to convert.
	samples := []float64{-40, 0, 25, 37, 100}

	fmt.Println("Temperature Converter")
	fmt.Println("=====================")
	// Print a header row. The %-12s pads text to 12 characters wide.
	fmt.Printf("%-12s %-14s %-12s %-10s\n", "Celsius", "Fahrenheit", "Kelvin", "Feels")
	fmt.Println("------------------------------------------------------")

	// Loop over every sample and print one converted row.
	for _, c := range samples {
		f := celsiusToFahrenheit(c)
		k := celsiusToKelvin(c)
		// %8.2f means: a number, 8 wide, with 2 decimal places.
		fmt.Printf("%8.2f C  %10.2f F  %8.2f K   %s\n", c, f, k, describe(c))
	}

	fmt.Println("------------------------------------------------------")
	fmt.Println("Tip: 0 C is freezing point and 100 C is boiling point of water.")
}

// Number Guessing Game (Auto-Play)
// Normally a person guesses a secret number. Here the COMPUTER plays
// against itself using a smart strategy called "binary search":
// it always guesses the middle of the remaining range.
// This avoids keyboard input and clearly shows how the strategy works.
package main

import "fmt"

// guessNumber plays one full game.
// It searches for `secret` inside the range low..high and
// returns how many guesses it needed.
func guessNumber(secret, low, high int) int {
	attempts := 0

	for low <= high {
		attempts++
		// The best guess is always the middle of the range.
		mid := (low + high) / 2
		fmt.Printf("Attempt %d: guessing %d ... ", attempts, mid)

		if mid == secret {
			fmt.Println("correct!")
			return attempts
		} else if mid < secret {
			fmt.Println("too low")
			low = mid + 1 // The answer must be higher.
		} else {
			fmt.Println("too high")
			high = mid - 1 // The answer must be lower.
		}
	}

	return attempts
}

func main() {
	// The range the game searches within.
	low, high := 1, 100

	// A few sample "secret" numbers to demonstrate the strategy.
	secrets := []int{42, 1, 100, 73}

	fmt.Printf("Number Guessing Game (searching %d to %d)\n", low, high)
	fmt.Println("==========================================")

	for _, secret := range secrets {
		fmt.Printf("\nSecret number is %d\n", secret)
		used := guessNumber(secret, low, high)
		fmt.Printf("Found it in %d guesses.\n", used)
	}

	fmt.Println("\nNotice: even with 100 numbers, it never needs more than 7 guesses!")
	fmt.Println("That is the power of binary search: it halves the range each time.")
}

// Temperature Converter
// Converts temperatures between Celsius, Fahrenheit, and Kelvin.
// No input needed: we use sample temperatures defined in the code.

// Convert Celsius to Fahrenheit: F = C * 9/5 + 32
fn celsius_to_fahrenheit(c: f64) -> f64 {
    c * 9.0 / 5.0 + 32.0
}

// Convert Celsius to Kelvin: K = C + 273.15
fn celsius_to_kelvin(c: f64) -> f64 {
    c + 273.15
}

fn main() {
    // Some interesting reference temperatures (in Celsius).
    let samples = [
        ("Water freezes", 0.0),
        ("Room temperature", 21.0),
        ("Human body", 37.0),
        ("Water boils", 100.0),
        ("A hot day in Harare", 32.0),
    ];

    println!("Temperature Conversion Table");
    println!("============================");
    // Print a header row, neatly aligned with fixed column widths.
    println!("{:<22} {:>10} {:>12} {:>10}", "Description", "Celsius", "Fahrenheit", "Kelvin");
    println!("{}", "-".repeat(58));

    for (label, c) in samples.iter() {
        let f = celsius_to_fahrenheit(*c);
        let k = celsius_to_kelvin(*c);
        // {:>10.1} means: right-aligned, width 10, 1 decimal place.
        println!("{:<22} {:>9.1}C {:>11.1}F {:>9.2}K", label, c, f, k);
    }

    println!("{}", "-".repeat(58));
    println!("Tip: 0K is absolute zero, the coldest temperature possible!");
}

// Number Guessing Game - Automatic Solver
// Normally a human guesses a secret number. Here the computer guesses it
// using "binary search": each guess cuts the remaining range in half.
// This shows a smart strategy that finds the answer very quickly.

fn main() {
    // The secret number the solver must find (between 1 and 100).
    let secret = 73;

    // The solver knows the number is somewhere in this range.
    let mut low = 1;
    let mut high = 100;
    let mut attempts = 0;

    println!("Number Guessing Game (computer guesses 1-100)");
    println!("Secret number is: {}", secret);
    println!("---------------------------------------------");

    loop {
        attempts += 1;
        // Guess the middle of the current range.
        let guess = (low + high) / 2;
        print!("Attempt {}: I guess {} ... ", attempts, guess);

        if guess == secret {
            // Found it! Stop the loop.
            println!("correct!");
            break;
        } else if guess < secret {
            // Too low: the answer must be above this guess.
            println!("too low.");
            low = guess + 1;
        } else {
            // Too high: the answer must be below this guess.
            println!("too high.");
            high = guess - 1;
        }
    }

    println!("---------------------------------------------");
    println!("Solved in {} attempts.", attempts);
    println!("Binary search needs at most 7 guesses for 1-100, because 2^7 = 128 > 100.");
}

// To-Do List Manager
// Demonstrates structs, vectors, and methods by managing a list of tasks.
// We add tasks, mark some as done, then print the list and a progress bar.

// A single task: what to do and whether it is finished.
struct Task {
    description: String,
    done: bool,
}

// A to-do list holds many tasks.
struct TodoList {
    tasks: Vec<Task>,
}

impl TodoList {
    // Create an empty list.
    fn new() -> TodoList {
        TodoList { tasks: Vec::new() }
    }

    // Add a new (unfinished) task to the list.
    fn add(&mut self, description: &str) {
        self.tasks.push(Task {
            description: description.to_string(),
            done: false,
        });
    }

    // Mark the task at the given position (1-based) as done.
    fn complete(&mut self, number: usize) {
        if number >= 1 && number <= self.tasks.len() {
            self.tasks[number - 1].done = true;
        }
    }

    // Count how many tasks are finished.
    fn completed_count(&self) -> usize {
        self.tasks.iter().filter(|t| t.done).count()
    }

    // Print the whole list with checkboxes and a progress bar.
    fn print(&self) {
        println!("My To-Do List");
        println!("=============");
        for (i, task) in self.tasks.iter().enumerate() {
            // [x] for done tasks, [ ] for pending ones.
            let mark = if task.done { "[x]" } else { "[ ]" };
            println!("{} {}. {}", mark, i + 1, task.description);
        }

        let done = self.completed_count();
        let total = self.tasks.len();
        // Build a simple text progress bar made of # and - characters.
        let filled = if total > 0 { done * 10 / total } else { 0 };
        let bar: String = "#".repeat(filled) + &"-".repeat(10 - filled);
        println!("-------------");
        println!("Progress: [{}] {}/{} tasks done", bar, done, total);
    }
}

fn main() {
    let mut list = TodoList::new();

    // Add some sample tasks.
    list.add("Finish maths homework");
    list.add("Read one chapter of a book");
    list.add("Tidy the bedroom");
    list.add("Practice Rust coding");

    // Mark a couple of tasks as completed.
    list.complete(1);
    list.complete(4);

    // Show the final list and progress.
    list.print();
}

