// Number Guessing Game (auto-played demo)
// Demonstrates how binary search efficiently finds a secret number
// by halving the search range on every guess.
#include <iostream>

int main() {
    int secret = 64;          // the number to find
    int low = 1, high = 100;  // current search range
    int attempts = 0;

    std::cout << "Number Guessing Game (computer plays itself)\n";
    std::cout << "Secret number is between 1 and 100.\n";
    std::cout << "Using binary search to find it fast.\n\n";

    while (low <= high) {
        int guess = (low + high) / 2; // always pick the middle of the range
        attempts++;
        std::cout << "Attempt " << attempts << ": guessing " << guess << " -> ";

        if (guess == secret) {
            std::cout << "correct!\n";
            break;
        } else if (guess < secret) {
            std::cout << "too low\n";
            low = guess + 1;  // discard the lower half
        } else {
            std::cout << "too high\n";
            high = guess - 1; // discard the upper half
        }
    }

    std::cout << "\nFound " << secret << " in only " << attempts << " attempts.\n";
    std::cout << "Binary search needs at most 7 guesses for 1-100!\n";
    return 0;
}

// Student Grade Report
// Computes averages and letter grades for a class from sample data,
// then prints the class average and identifies the top student.
#include <iostream>
#include <iomanip>
#include <string>
#include <vector>

struct Student {
    std::string name;
    std::vector<int> scores;
};

// Average of a list of test scores
double average(const std::vector<int>& scores) {
    int total = 0;
    for (int s : scores) total += s;
    return scores.empty() ? 0.0 : static_cast<double>(total) / scores.size();
}

// Convert a numeric average into a letter grade
char letterGrade(double avg) {
    if (avg >= 80) return 'A';
    if (avg >= 70) return 'B';
    if (avg >= 60) return 'C';
    if (avg >= 50) return 'D';
    return 'F';
}

int main() {
    // Sample class data: name and three test scores each
    std::vector<Student> students = {
        {"Tendai", {85, 92, 78}},
        {"Chipo",  {60, 55, 70}},
        {"Farai",  {95, 88, 91}},
        {"Rudo",   {40, 52, 48}}
    };

    std::cout << "Class Grade Report\n";
    std::cout << "==================\n";
    std::cout << std::left << std::setw(12) << "Name"
              << std::setw(10) << "Average"
              << "Grade\n";

    double classTotal = 0.0;

    // Print each student's average and grade
    std::cout << std::fixed << std::setprecision(1);
    for (const auto& st : students) {
        double avg = average(st.scores);
        classTotal += avg;
        std::cout << std::left << std::setw(12) << st.name
                  << std::setw(10) << avg
                  << letterGrade(avg) << "\n";
    }

    // Find the top performer
    double best = -1.0;
    std::string topStudent;
    for (const auto& st : students) {
        double avg = average(st.scores);
        if (avg > best) { best = avg; topStudent = st.name; }
    }

    std::cout << "\nClass average: " << classTotal / students.size() << "\n";
    std::cout << "Top student: " << topStudent << " (" << best << ")\n";
    return 0;
}

