// Number Guessing Game - Automatic Player
// Normally a human guesses a secret number, but this runtime has no keyboard
// input, so the COMPUTER plays against itself using a smart "binary search"
// strategy: it always guesses the middle of the remaining range.
// This teaches how halving the search space finds any number very fast.

using System;

class Program
{
    static void Main()
    {
        const int low = 1;
        const int high = 100;
        int secret = 73; // The hidden number the player is trying to find.

        Console.WriteLine("Number Guessing Game (the computer guesses!)");
        Console.WriteLine($"A secret number between {low} and {high} has been chosen.");
        Console.WriteLine($"(For this demo the secret is {secret}.)");
        Console.WriteLine();

        int min = low;
        int max = high;
        int attempts = 0;

        // Keep guessing until the guess matches the secret.
        while (true)
        {
            attempts++;

            // The smart move: guess the middle of the current range.
            int guess = (min + max) / 2;
            Console.Write($"Attempt {attempts}: I guess {guess}. ");

            if (guess == secret)
            {
                Console.WriteLine("Correct!");
                break;
            }
            else if (guess < secret)
            {
                // Too low, so the answer must be above the guess.
                Console.WriteLine("Too low. I'll aim higher.");
                min = guess + 1;
            }
            else
            {
                // Too high, so the answer must be below the guess.
                Console.WriteLine("Too high. I'll aim lower.");
                max = guess - 1;
            }
        }

        Console.WriteLine();
        Console.WriteLine($"Found {secret} in just {attempts} attempts!");
        Console.WriteLine("Binary search can find any number from 1-100 in 7 guesses or fewer.");
    }
}

