// Represents a single task on the list.
class TodoItem
{
    public string Title { get; }
    public int Priority { get; }
    public bool Done { get; set; }

    public TodoItem(string title, int priority)
    {
        Title = title;
        Priority = priority;
        Done = false;
    }
}

// Manages a collection of TodoItem objects.
class TodoList
{
    private readonly List<TodoItem> _items = new List<TodoItem>();

    // Add a new task with a priority (defaults to 2 = medium).
    public void Add(string title, int priority = 2)
    {
        _items.Add(new TodoItem(title, priority));
    }

    // Find a task by name and mark it as done.
    public void Complete(string title)
    {
        var item = _items.FirstOrDefault(t => t.Title == title);
        if (item != null)
            item.Done = true;
    }

    // Print a tidy report sorted by priority then by title.
    public void PrintReport()
    {
        Console.WriteLine("My To-Do List");
        Console.WriteLine("=============");
        Console.WriteLine();

        // Order by priority (1 first), then alphabetically by title.
        var ordered = _items.OrderBy(t => t.Priority).ThenBy(t => t.Title);

        foreach (var item in ordered)
        {
            // [x] for done, [ ] for not done.
            string box = item.Done ? "[x]" : "[ ]";
            string stars = new string('*', item.Priority); // simple priority marker
            Console.WriteLine($"{box} (P{item.Priority} {stars,-3}) {item.Title}");
        }

        // Print a small summary at the bottom.
        int total = _items.Count;
        int done = _items.Count(t => t.Done);
        int remaining = total - done;

        Console.WriteLine();
        Console.WriteLine($"Summary: {done} of {total} done, {remaining} remaining.");

        if (remaining == 0)
            Console.WriteLine("Great job - everything is finished!");
        else
            Console.WriteLine("Keep going - you can do it!");
    }
}

// Caesar Cipher Encoder & Decoder
// A Caesar cipher shifts every letter in a message by a fixed number of steps.
// For example, with a shift of 3: A becomes D, B becomes E, Z wraps around to C!
// Julius Caesar actually used this to send secret military messages. Cool, right?

// This function encodes OR decodes a message depending on the shift direction.
function caesarCipher(text, shift) {
  // Make sure the shift wraps nicely between 0 and 25
  shift = ((shift % 26) + 26) % 26;

  let result = '';

  for (let i = 0; i < text.length; i++) {
    const char = text[i];
    const code = text.charCodeAt(i);

    if (code >= 65 && code <= 90) {
      // Uppercase letter: shift it, wrapping around the alphabet
      result += String.fromCharCode(((code - 65 + shift) % 26) + 65);
    } else if (code >= 97 && code <= 122) {
      // Lowercase letter: same idea, different ASCII range
      result += String.fromCharCode(((code - 97 + shift) % 26) + 97);
    } else {
      // Spaces, punctuation, numbers — leave them as-is
      result += char;
    }
  }

  return result;
}

// To decode, just shift in the opposite direction!
function encode(text, shift) {
  return caesarCipher(text, shift);
}

function decode(text, shift) {
  return caesarCipher(text, -shift);
}

// --- Let's try it out! ---

const secretShift = 13; // ROT13 is a popular shift-by-13 cipher
const originalMessage = 'Hello, World! Meet me at noon.';

const encoded = encode(originalMessage, secretShift);
const decoded = decode(encoded, secretShift);

console.log('=== Caesar Cipher Demo ===');
console.log('Shift amount   :', secretShift);
console.log('Original       :', originalMessage);
console.log('Encoded        :', encoded);
console.log('Decoded back   :', decoded);
