// Word Frequency Counter
// Ever read a book and thought "does this author say 'the' WAY too much"?
// Let's build a program that counts every word in a passage and ranks them!

// Clean up a word: lowercase it and strip punctuation from both ends
function cleanWord(word) {
  return word
    .toLowerCase()
    .replace(/^[^a-z0-9]+/, '') // remove leading punctuation
    .replace(/[^a-z0-9]+$/, ''); // remove trailing punctuation
}

// Count how often each word appears in a block of text
function countWords(text) {
  const words = text.split(/\s+/); // split on any whitespace
  const frequency = {};

  for (const raw of words) {
    const word = cleanWord(raw);
    if (word.length === 0) continue; // skip empty strings

    // If we've seen this word before, add 1; otherwise start at 1
    frequency[word] = (frequency[word] || 0) + 1;
  }

  return frequency;
}

// Sort the frequency map and return the top N entries
function topWords(frequency, n = 10) {
  return Object.entries(frequency)
    .sort((a, b) => b[1] - a[1]) // sort by count, highest first
    .slice(0, n);
}

// --- Sample text: opening lines of a famous public-domain novel ---
const sampleText = `
