  it was the spring of hope, it was the winter of despair,
  we had everything before us, we had nothing before us,
  we were all going direct to Heaven, we were all going direct the other way.
`;
// (A Tale of Two Cities — Charles Dickens, 1859)

const frequency = countWords(sampleText);
const top = topWords(frequency, 10);

console.log('=== Word Frequency Counter ===');
console.log('Text: Opening lines of "A Tale of Two Cities" by Charles Dickens');
console.log();

// Calculate total words for percentage display
const totalWords = Object.values(frequency).reduce((sum, c) => sum + c, 0);
const uniqueWords = Object.keys(frequency).length;

console.log(`Total words : ${totalWords}`);
console.log(`Unique words: ${uniqueWords}`);
console.log();
console.log('Top 10 most frequent words:');
console.log();

// Find the longest word for neat column alignment
const maxWordLen = Math.max(...top.map(([w]) => w.length));

for (let i = 0; i < top.length; i++) {
  const [word, count] = top[i];
  const rank = String(i + 1).padStart(2, ' ');
  const paddedWord = word.padEnd(maxWordLen, ' ');
