// =============================================
// Student Gradebook — TypeScript Example
// Learn: interfaces, enums, generics, arrays
// =============================================

// An enum lists a fixed set of named values.
// Here we use it for letter grades so we can't
// accidentally type "AA" or "Z" by mistake.
enum LetterGrade {
  A = "A",
  B = "B",
  C = "C",
  D = "D",
  F = "F",
}

// An interface describes the shape of an object.
// TypeScript will warn us if we forget a field.
interface Student {
  name: string;
  scores: number[]; // array of test scores (0–100)
}

interface ReportCard {
  name: string;
  average: number;
  grade: LetterGrade;
}

// A generic helper — the <T> means "works for any type T".
// This one adds up all numbers in any number array.
function sum(numbers: number[]): number {
  return numbers.reduce((total, n) => total + n, 0);
}

// Calculate the average of an array of numbers.
function average(numbers: number[]): number {
  if (numbers.length === 0) return 0;
  return sum(numbers) / numbers.length;
}

// Convert a numeric average to a LetterGrade enum value.
function toLetterGrade(avg: number): LetterGrade {
  if (avg >= 90) return LetterGrade.A;
  if (avg >= 80) return LetterGrade.B;
  if (avg >= 70) return LetterGrade.C;
  if (avg >= 60) return LetterGrade.D;
  return LetterGrade.F;
}

// Generate a ReportCard for one Student.
function makeReportCard(student: Student): ReportCard {
  const avg = average(student.scores);
  return {
    name: student.name,
    average: Math.round(avg * 10) / 10, // round to 1 decimal
    grade: toLetterGrade(avg),
  };
}

// ---- Sample Data ----
const students: Student[] = [
  { name: "Alice",   scores: [92, 88, 95, 91] },
  { name: "Bob",     scores: [73, 67, 80, 71] },
  { name: "Charlie", scores: [55, 60, 58, 62] },
  { name: "Diana",   scores: [100, 98, 97, 99] },
