console.log(`${ "Name".padEnd(10) } ${ "Average".padEnd(10) } Grade`);
console.log("-".repeat(30));

const reports: ReportCard[] = students.map(makeReportCard);

for (const report of reports) {
  const namePad = report.name.padEnd(10);
  const avgPad  = String(report.average).padEnd(10);
  console.log(`${namePad} ${avgPad} ${report.grade}`);
}

