// =============================================
// Shape Area Calculator — TypeScript Example
// Learn: discriminated unions, exhaustive switch,
//        type aliases, readonly properties
// =============================================

// Each shape type has a unique "kind" tag.
// TypeScript uses the tag to narrow the type
// inside if/switch blocks — this is called a
// DISCRIMINATED UNION (or tagged union).

type Circle = {
  readonly kind: "circle";
  readonly radius: number;
};

type Rectangle = {
  readonly kind: "rectangle";
  readonly width: number;
  readonly height: number;
};

type Triangle = {
  readonly kind: "triangle";
  readonly base: number;
  readonly height: number;
};

// A union type that can be ANY of the three shapes.
type Shape = Circle | Rectangle | Triangle;

// Calculate area — TypeScript narrows the type in
// each case branch, so we only access valid fields.
function area(shape: Shape): number {
  switch (shape.kind) {
    case "circle":
      // Inside here, TypeScript knows shape is Circle
      return Math.PI * shape.radius ** 2;

    case "rectangle":
      return shape.width * shape.height;

    case "triangle":
      return 0.5 * shape.base * shape.height;

    default:
      // The "never" trick: if we add a new shape but
      // forget to handle it, TypeScript shows an error!
      const _exhaustive: never = shape;
      return _exhaustive;
  }
}

// Return a human-friendly label for a shape.
function describe(shape: Shape): string {
  switch (shape.kind) {
    case "circle":
      return `Circle (radius=${shape.radius})`;
    case "rectangle":
      return `Rectangle (${shape.width}×${shape.height})`;
    case "triangle":
      return `Triangle (base=${shape.base}, height=${shape.height})`;
    default:
      const _exhaustive: never = shape;
      return _exhaustive;
  }
}

// ---- Sample Shapes ----
const shapes: Shape[] = [
  { kind: "circle",    radius: 5 },
  { kind: "rectangle", width: 8,   height: 4 },
  { kind: "triangle",  base: 6,    height: 9 },
  { kind: "circle",    radius: 3 },
  { kind: "rectangle", width: 12,  height: 7 },
];

// ---- Print Results ----
console.log("====== Shape Area Calculator ======");
for (const shape of shapes) {
  const label = describe(shape);
  const result = area(shape).toFixed(2);
  console.log(`${label.padEnd(35)} Area = ${result}`);
}

// Find the largest shape using a typed comparison.
const largest = shapes.reduce((best, current) =>
  area(current) > area(best) ? current : best
);
console.log(`\nLargest shape: ${describe(largest)} (area = ${area(largest).toFixed(2)})`);

// =============================================
// Generic Utilities Toolkit — TypeScript Example
// Learn: generics (<T>), type constraints,
//        higher-order functions, Record types
// =============================================

// GENERICS let us write ONE function that works
// safely with MANY different types.
// Think of <T> as a "type variable" — a placeholder
// that gets filled in when you call the function.

// --- Generic filter ---
// Works like Array.filter but with an explicit
// typed predicate so TypeScript keeps things safe.
function filterBy<T>(items: T[], predicate: (item: T) => boolean): T[] {
  const result: T[] = [];
  for (const item of items) {
    if (predicate(item)) {
      result.push(item);
    }
  }
  return result;
}

// --- Generic transform (map) ---
// Turns an array of T into an array of U.
// Both T and U are inferred from how you call it.
function transformAll<T, U>(items: T[], transform: (item: T) => U): U[] {
  const result: U[] = [];
  for (const item of items) {
    result.push(transform(item));
  }
  return result;
}

// --- Generic groupBy ---
// Groups items into a Record (like a dictionary)
// keyed by whatever string the selector returns.
function groupBy<T>(items: T[], selector: (item: T) => string): Record<string, T[]> {
  const groups: Record<string, T[]> = {};
  for (const item of items) {
    const key = selector(item);
    if (!groups[key]) {
      groups[key] = [];
    }
    groups[key].push(item);
  }
  return groups;
}

// ---- Domain: Product inventory ----
type Category = "Electronics" | "Clothing" | "Food";

interface Product {
  name: string;
  category: Category;
  price: number;   // in USD
  inStock: boolean;
}

const inventory: Product[] = [
  { name: "Laptop",      category: "Electronics", price: 999,  inStock: true  },
  { name: "T-Shirt",     category: "Clothing",    price: 25,   inStock: true  },
  { name: "Headphones",  category: "Electronics", price: 149,  inStock: false },
  { name: "Jeans",       category: "Clothing",    price: 60,   inStock: true  },
  { name: "Rice (5 kg)", category: "Food",        price: 8,    inStock: true  },
  { name: "Keyboard",    category: "Electronics", price: 79,   inStock: true  },
  { name: "Bread",       category: "Food",        price: 3,    inStock: false },
  { name: "Sneakers",    category: "Clothing",    price: 95,   inStock: true  },
];

// ---- 1. Filter: only in-stock items ----
const inStock = filterBy(inventory, p => p.inStock);
console.log("=== In-Stock Products ===");
for (const p of inStock) {
  console.log(`  ${p.name.padEnd(16)} $${p.price}`);
}

// ---- 2. Transform: extract price list ----
const priceList = transformAll(inStock, p => ({ name: p.name, price: p.price }));
const totalValue = priceList.reduce((sum, item) => sum + item.price, 0);
console.log(`\nTotal in-stock value: $${totalValue}`);

// ---- 3. GroupBy: sort by category ----
const byCategory = groupBy(inventory, p => p.category);
console.log("\n=== Products by Category ===");
for (const [category, products] of Object.entries(byCategory)) {
  const names = products.map(p => p.name).join(", ");
  console.log(`  ${category}: ${names}`);
}

// ---- 4. Chained: cheapest in-stock Electronics ----
const electronics = filterBy(inStock, p => p.category === "Electronics");
const cheapest = electronics.reduce((best, p) => p.price < best.price ? p : best);
console.log(`\nCheapest in-stock Electronic: ${cheapest.name} at $${cheapest.price}`);

/* ============================================================
   Pure-CSS Animated Bar Chart
   Key concepts:
     1. CSS custom properties (--pct, --color, --delay)
     2. @keyframes to animate bars growing upward
     3. transform-origin to grow from the bottom
     4. animation-delay to stagger each bar
   ============================================================ */

/* --- Reset & base --- */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;

  /* A dark gradient background makes the coloured bars pop */
  background: linear-gradient(135deg, #0f172a 0%, #1e1b4b 100%);
  font-family: 'Segoe UI', system-ui, sans-serif;
  color: #f1f5f9;
  padding: 2rem 1rem;
}

/* --- Card that holds the whole chart --- */
.chart-wrapper {
  position: relative;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 1.5rem;
  padding: 2rem 2rem 1.5rem;
  max-width: 680px;
  width: 100%;

  /* Frosted-glass look */
  backdrop-filter: blur(12px);
}

h1 {
  font-size: 1.5rem;
  font-weight: 700;
  text-align: center;
  margin-bottom: 0.25rem;
}

.subtitle {
  text-align: center;
  font-size: 0.875rem;
  color: #94a3b8;
  margin-bottom: 1.75rem;
}

/* ============================================================
   CHART LAYOUT
   We use flexbox to sit the bars side-by-side and align them
   to the BOTTOM so short bars and tall bars all start from
   the same baseline.
   ============================================================ */
.chart {
  display: flex;
  align-items: flex-end;   /* align all bars to the bottom */
  justify-content: space-around;
  height: 260px;           /* fixed height = 100% of the scale */
  position: relative;
  padding: 0 0.5rem;

  /* A subtle baseline */
  border-bottom: 2px solid rgba(255, 255, 255, 0.15);
}

/* ============================================================
   BAR GROUP — wraps one bar + its bottom label
   ============================================================ */
.bar-group {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.5rem;
  flex: 1;

  /* Stagger the animation using the bar group's position.
     We use nth-child delays defined below. */
}

/* ============================================================
   THE BAR ITSELF
   --pct  : how tall the bar should be (set via inline style)
   --color: the bar's accent colour (set via inline style)
   ============================================================ */
.bar {
  position: relative;
  width: 100%;
  max-width: 52px;

  /* The bar starts at height 0 and grows to --pct of the
     chart height via the 'grow' keyframe animation. */
  height: var(--pct);

  /* Give the bar its colour with a gradient for depth */
  background: linear-gradient(
    to top,
    var(--color),
    color-mix(in srgb, var(--color) 60%, white)
  );

  border-radius: 6px 6px 0 0;

  /* ---- THE ANIMATION ----
     Name      : grow (defined below)
     Duration  : 1.2s
     Timing    : cubic-bezier gives a nice "bounce" feel
     Fill-mode : forwards keeps the bar visible after it grows
     The delay staggers each bar (overridden per nth-child)  */
  animation: grow 1.2s cubic-bezier(0.34, 1.56, 0.64, 1) both;

  /* Subtle inner glow at the top edge */
  box-shadow:
    0 -4px 16px color-mix(in srgb, var(--color) 60%, transparent),
    inset 0 1px 0 rgba(255,255,255,0.25);
}

/* ============================================================
   @keyframes grow
   We animate 'transform: scaleY()' rather than 'height'
   because transforms are GPU-accelerated (smooth on any device).

   transform-origin: bottom  — so the bar grows UPWARD from
   the baseline, not downward from the top.
   ============================================================ */
@keyframes grow {
  from {
    transform: scaleY(0);
    transform-origin: bottom;
  }
  to {
    transform: scaleY(1);
    transform-origin: bottom;
  }
}

/* ============================================================
   STAGGERED DELAYS
   Each bar-group gets a slightly later start so bars appear
   one after another instead of all at once.
   ============================================================ */
.bar-group:nth-child(1) .bar { animation-delay: 0.0s; }
.bar-group:nth-child(2) .bar { animation-delay: 0.1s; }
.bar-group:nth-child(3) .bar { animation-delay: 0.2s; }
.bar-group:nth-child(4) .bar { animation-delay: 0.3s; }
.bar-group:nth-child(5) .bar { animation-delay: 0.4s; }
.bar-group:nth-child(6) .bar { animation-delay: 0.5s; }
.bar-group:nth-child(7) .bar { animation-delay: 0.6s; }

/* ============================================================
   VALUE LABEL — floats above each bar
   ============================================================ */
.label-top {
  position: absolute;
  top: -1.6rem;
  left: 50%;
  transform: translateX(-50%);
  font-size: 0.72rem;
  font-weight: 700;
  color: var(--color);
  white-space: nowrap;

  /* Fade in after the bar has grown */
  opacity: 0;
  animation: fadein 0.4s ease forwards;
}

/* Each label waits for its bar to mostly finish growing */
.bar-group:nth-child(1) .label-top { animation-delay: 0.9s; }
.bar-group:nth-child(2) .label-top { animation-delay: 1.0s; }
.bar-group:nth-child(3) .label-top { animation-delay: 1.1s; }
.bar-group:nth-child(4) .label-top { animation-delay: 1.2s; }
.bar-group:nth-child(5) .label-top { animation-delay: 1.3s; }
.bar-group:nth-child(6) .label-top { animation-delay: 1.4s; }
.bar-group:nth-child(7) .label-top { animation-delay: 1.5s; }

@keyframes fadein {
  to { opacity: 1; }
}

/* --- Language name below each bar --- */
.label-bottom {
  font-size: 0.7rem;
  color: #94a3b8;
  text-align: center;
  line-height: 1.2;
  max-width: 56px;
}

/* ============================================================
   GRID LINES (decorative horizontal rules)
   These are absolutely positioned inside .chart-wrapper.
   ============================================================ */
.grid-lines {
  /* Stack 5 labels top-to-bottom, spread evenly */
  position: absolute;
  left: 1rem;
  /* Top of the chart area to the baseline — eyeballed to align */
  top: 5.5rem;
  height: 260px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  pointer-events: none;
}

.grid-lines span {
  font-size: 0.65rem;
  color: rgba(148, 163, 184, 0.5);
  display: flex;
  align-items: center;
  gap: 0.4rem;
}

/* Draw the actual line using a pseudo-element */
.grid-lines span::after {
  content: '';
  display: block;
  width: 560px;   /* wide enough to cross the chart */
  height: 1px;
  background: rgba(255, 255, 255, 0.07);
}

/* ============================================================
   RESPONSIVE — on small screens shrink text & chart height
   ============================================================ */
@media (max-width: 480px) {
  .chart {
    height: 180px;
  }
  .label-bottom {
    font-size: 0.6rem;
  }
  .grid-lines {
    top: 5.5rem;
    height: 180px;
  }
  .grid-lines span::after {
    width: 320px;
  }
}

/* ============================================================
   Hover-Glow Button Collection
   Key concepts:
     1. CSS transitions — smooth property changes on hover
     2. ::before / ::after pseudo-elements — extra layers
        with no extra HTML needed
     3. transform — move, scale, rotate elements
     4. box-shadow — depth and glow effects
     5. overflow: hidden — clip sliding/shimmer layers
     6. @keyframes — looping animations on hover
   ============================================================ */

/* --- Reset & base --- */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  background: #0d0d1a;
  font-family: 'Segoe UI', system-ui, sans-serif;
  color: #e2e8f0;
  padding: 3rem 1.5rem;
}

main {
  max-width: 900px;
  margin: 0 auto;
}

h1 {
  font-size: 2rem;
  font-weight: 800;
  text-align: center;
  margin-bottom: 0.4rem;
}

.intro {
  text-align: center;
  color: #94a3b8;
  margin-bottom: 2.5rem;
  line-height: 1.6;
}

/* --- Card grid layout --- */
.grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
  gap: 1.5rem;
}

.card {
  background: rgba(255,255,255,0.04);
  border: 1px solid rgba(255,255,255,0.08);
  border-radius: 1rem;
  padding: 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.card h2 {
  font-size: 1rem;
  font-weight: 700;
  color: #f1f5f9;
}

.card p {
  font-size: 0.825rem;
  color: #94a3b8;
  line-height: 1.5;
  flex: 1;
}

/* ============================================================
   BASE BUTTON STYLES
   All buttons share these fundamentals.
   ============================================================ */
.btn {
  position: relative;     /* needed so ::before/::after position inside */
  overflow: hidden;       /* clips pseudo-element layers to the button */
  cursor: pointer;
  border: none;
  border-radius: 0.5rem;
  padding: 0.7rem 1.5rem;
  font-size: 0.95rem;
  font-weight: 600;
  letter-spacing: 0.03em;
  font-family: inherit;

  /* Smooth property changes over 0.3 s */
  transition: transform 0.2s ease, box-shadow 0.3s ease, color 0.3s ease;
}

/* Slight lift on hover shared by all buttons */
.btn:hover {
  transform: translateY(-2px);
}

/* ============================================================
   1. NEON PULSE
   The glow is a box-shadow. On hover we trigger a CSS
   @keyframes animation that pulses the glow in and out.
   ============================================================ */
.btn--neon {
  background: transparent;
  color: #a78bfa;
  border: 2px solid #a78bfa;
  border-radius: 2rem;   /* pill shape */
}

.btn--neon:hover {
  color: #fff;
  animation: neon-pulse 1s ease infinite;
  background: rgba(167, 139, 250, 0.15);
}

/* The animation cycles the box-shadow size */
@keyframes neon-pulse {
  0%, 100% {
    box-shadow:
      0 0  8px #a78bfa,
      0 0 20px #a78bfa,
      0 0 40px #a78bfa;
  }
  50% {
    box-shadow:
      0 0  4px #a78bfa,
      0 0 10px #a78bfa,
      0 0 20px #a78bfa;
  }
}

/* ============================================================
   2. SLIDE FILL
   A ::before pseudo-element starts off-screen to the left
   (translateX(-100%)) and slides to translateX(0) on hover.
   The button text sits above it via position: relative + z-index.
   ============================================================ */
.btn--slide {
  background: transparent;
  color: #38bdf8;
  border: 2px solid #38bdf8;
}

/* The fill layer */
.btn--slide::before {
  content: '';              /* pseudo-elements need content: '' */
  position: absolute;
  inset: 0;                 /* fill the entire button */
  background: #38bdf8;
  transform: translateX(-100%);  /* start fully off to the left */
  transition: transform 0.35s ease;
  z-index: 0;               /* behind the text */
}

/* The button text must be above the fill layer */
.btn--slide span,
.btn--slide {
  z-index: 1;
}

/* On hover: slide the fill into view */
.btn--slide:hover::before {
  transform: translateX(0);
}

.btn--slide:hover {
  color: #0d0d1a;           /* text goes dark when fill arrives */
  transform: translateY(-2px);
}

/* ============================================================
   3. 3-D PRESS
   A thick box-shadow below the button acts as its "side".
   On hover, we push the button down (translateY) and shrink
   the shadow to make it look like it's being pressed.
   ============================================================ */
.btn--press {
  background: #f97316;
  color: #fff;
  border: none;
  /* bottom shadow = the 3-D "thickness" */
  box-shadow: 0 6px 0 #c2410c;
  transition: transform 0.1s ease, box-shadow 0.1s ease;
}

.btn--press:hover {
  transform: translateY(4px);    /* push button down by 4 px */
  box-shadow: 0 2px 0 #c2410c;  /* shadow shrinks by same amount */
}

.btn--press:active {
  transform: translateY(6px);
  box-shadow: 0 0px 0 #c2410c;
}

/* ============================================================
   4. SHIMMER SWEEP
   A ::after pseudo-element is a narrow diagonal white strip.
   It starts off the left edge and slides past the right edge
   when the button is hovered, creating a "light sweep" effect.
   ============================================================ */
.btn--shimmer {
  background: linear-gradient(135deg, #6366f1, #8b5cf6);
  color: #fff;
}

/* The shimmer strip */
.btn--shimmer::after {
  content: '';
  position: absolute;
  top: -50%;             /* taller than the button so the angle shows */
  left: -75%;            /* start off the left edge */
  width: 50%;            /* narrow strip */
  height: 200%;
  background: rgba(255, 255, 255, 0.3);
  transform: skewX(-20deg);  /* angle the strip */
  transition: left 0.5s ease;
}

/* On hover: slide the strip across to the right */
.btn--shimmer:hover::after {
  left: 130%;
}

.btn--shimmer:hover {
  box-shadow: 0 8px 24px rgba(99, 102, 241, 0.5);
}

/* ============================================================
   5. BORDER DRAW
   We draw four thin border "lines" using ::before and ::after
   that are clipped to zero width/height and expand on hover.
   A simpler single-element trick: use outline with a growing
   offset, combined with color transitions.
   ============================================================ */
.btn--border {
  background: transparent;
  color: #f1f5f9;
  outline: 2px solid transparent;
  outline-offset: 0px;
  /* Transition outline properties */
  transition:
    outline-color 0.3s ease,
    outline-offset 0.3s ease,
    color 0.3s ease,
    background 0.3s ease;
}

.btn--border:hover {
  outline-color: #10b981;
  outline-offset: 4px;    /* outline expands away from the button */
  color: #10b981;
  background: rgba(16, 185, 129, 0.1);
}

/* ============================================================
   6. RIPPLE RING
   The ::before pseudo-element starts as a tiny circle scaled
   to 0, then on hover it scales up and fades out — like a
   ripple radiating outward.
   ============================================================ */
.btn--ripple {
  background: linear-gradient(135deg, #ec4899, #f97316);
  color: #fff;
}

.btn--ripple::before {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;  /* match the button's own rounded corners */
  border: 2px solid rgba(249, 115, 22, 0.8);

  /* Start at the button's exact size (scale 1) with full opacity */
  transform: scale(1);
  opacity: 1;

  /* No transition by default */
  transition: none;
}

/* On hover: expand and fade */
.btn--ripple:hover::before {
  transform: scale(1.6);
  opacity: 0;
  transition: transform 0.6s ease, opacity 0.6s ease;
}

.btn--ripple:hover {
  box-shadow: 0 0 24px rgba(249, 115, 22, 0.5);
}

/* ============================================================
   CSS Grid Mosaic Layout
   Key concepts:
     1. display: grid — activates the grid on a container
     2. grid-template-columns / grid-template-rows — define
        the columns and rows (tracks) of the grid
     3. grid-template-areas — name each cell so children can
        place themselves by name instead of by line numbers
     4. grid-area — tells a child WHICH named area to fill
     5. grid-column / grid-row span — stretch across cells
     6. Hover transitions — subtle scale & caption reveal
   ============================================================ */

/* --- Reset & base --- */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  background: #0a0a0a;
  font-family: 'Segoe UI', system-ui, sans-serif;
  color: #f1f5f9;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2rem;
  padding: 2.5rem 1rem;
}

header {
  text-align: center;
}

header h1 {
  font-size: 2rem;
  font-weight: 800;
}

header p {
  color: #64748b;
  margin-top: 0.25rem;
}

footer {
  font-size: 0.8rem;
  color: #475569;
  text-align: center;
}

/* ============================================================
   THE GRID CONTAINER

   We define 4 equal columns and 3 rows.
   Columns: repeat(4, 1fr) — four tracks each taking 1
            fraction of the available space.
   Rows   : three rows at defined heights.

   grid-template-areas draws a map of the layout using
   quoted strings — each string is one row, each word is one
   cell. The SAME word repeated means that tile spans those cells.
   ============================================================ */
.mosaic {
  display: grid;

  /* 4 equal-width columns */
  grid-template-columns: repeat(4, 1fr);

  /* 3 rows: first two rows are 220px tall, third is 180px */
  grid-template-rows: 220px 220px 180px;

  /* Gap between tiles */
  gap: 0.75rem;

  /* Limit width so the grid looks good on wide screens */
  max-width: 900px;
  width: 100%;

  /*
    Template areas — think of this as a picture of the grid:

    Row 1: hero  hero  wide  tall
    Row 2: hero  hero  mush  tall
    Row 3: ocean ocean night pool

    'hero' appears in a 2×2 block  → spans 2 cols & 2 rows
    'wide' is 1 col × 1 row
    'tall' is 1 col × 2 rows
    All others are 1×1.
  */
  grid-template-areas:
    "hero  hero  wide  tall"
    "hero  hero  mush  tall"
    "ocean ocean night pool";
}

/* ============================================================
   ASSIGNING TILES TO AREAS
   Each tile class maps to a named area from the template.
   ============================================================ */

/* The big hero tile — takes the name 'hero' from the map */
.tile--hero  { grid-area: hero;  }

/* Wide top-right tile */
.tile--wide  { grid-area: wide;  }

/* Tall right-side tile spanning two rows */
.tile--tall  { grid-area: tall;  }

/* Remaining 1×1 tiles — assigned in source order.
   We can also name them explicitly for clarity. */
.tile:nth-child(4) { grid-area: mush;  }
.tile:nth-child(5) { grid-area: ocean; }
.tile:nth-child(6) { grid-area: night; }
.tile:nth-child(7) { grid-area: pool;  }

/* ============================================================
   TILE INNER — the visual box inside each tile
   We use an inner element so we can clip its overflow
   (for the hover zoom) without clipping the grid gap.
   ============================================================ */
.tile {
  /* Remove default article border */
  border: none;
}

.tile__inner {
  position: relative;
  width: 100%;
  height: 100%;
  border-radius: 0.75rem;
  overflow: hidden;   /* keeps the zoomed image clipped */

  /* Each tile gets its colour via the --bg custom property
     set as an inline style on the HTML element */
  background-color: var(--bg, #1e293b);

