  );

  cursor: pointer;
  transition: transform 0.35s ease;
}

/* ============================================================
   HOVER ZOOM
   We scale the inner div (not the grid cell) so the zoom
   stays clipped inside the tile's border-radius.
   ============================================================ */
.tile__inner:hover {
