}

/* ============================================================
   EMOJI — acts as the "photo" in each tile
   ============================================================ */
.tile__emoji {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;

  /* Hero tile emoji is bigger */
