   ============================================================ */
.tile__caption {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  padding: 1rem;

  /* Gradient so text is readable over any colour */
  background: linear-gradient(to top, rgba(0,0,0,0.7) 0%, transparent 100%);

