import (
	"fmt"
	"sort"
	"strings"
)

func main() {
	// Our sample text — try changing this to any sentence you like!
	text := "the quick brown fox jumps over the lazy dog the fox was very quick and the dog was very lazy"

	// Split the text into individual words
	words := strings.Fields(text)

	// A map lets us store a count for each unique word.
	// Think of it like a tally chart: word → how many times seen.
	frequency := make(map[string]int)

	for _, word := range words {
		frequency[word]++ // If the word is new, Go starts it at 0 then adds 1
	}

	// We can't sort a map directly, so collect all the unique words into a slice
	unique := make([]string, 0, len(frequency))
	for word := range frequency {
		unique = append(unique, word)
	}

	// Sort by frequency (highest first). When counts are equal, sort alphabetically.
	sort.Slice(unique, func(i, j int) bool {
		if frequency[unique[i]] != frequency[unique[j]] {
			return frequency[unique[i]] > frequency[unique[j]]
		}
		return unique[i] < unique[j]
	})

	fmt.Println("=== Word Frequency Counter ===")
	fmt.Printf("Total words: %d | Unique words: %d\n\n", len(words), len(unique))
	fmt.Printf("%-12s  %s\n", "WORD", "COUNT")
	fmt.Println(strings.Repeat("-", 20))

	for _, word := range unique {
		// Print a little bar made of stars to show the count visually
		bar := strings.Repeat("*", frequency[word])
		fmt.Printf("%-12s  %d  %s\n", word, frequency[word], bar)
	}
}

