import (
	"fmt"
	"strings"
)

// encrypt shifts every letter in the message forward by 'shift' positions.
// Non-letter characters (spaces, punctuation) are left unchanged.
func encrypt(message string, shift int) string {
	// Make sure shift is in the range 0-25
	shift = shift % 26

	var result strings.Builder

	for _, ch := range message {
		switch {
		case ch >= 'A' && ch <= 'Z':
			// Shift uppercase letters, wrap around with modulo
			result.WriteRune('A' + (ch-'A'+rune(shift))%26)
		case ch >= 'a' && ch <= 'z':
			// Shift lowercase letters
			result.WriteRune('a' + (ch-'a'+rune(shift))%26)
		default:
			// Keep spaces, numbers, punctuation as-is
			result.WriteRune(ch)
		}
	}

	return result.String()
}

// decrypt is just encrypting in the opposite direction!
func decrypt(message string, shift int) string {
	// Shifting forward by (26 - shift) is the same as shifting backward
	return encrypt(message, 26-shift)
}

func main() {
	original := "Hello, World! Go is awesome."
	shift := 13 // ROT13 is a famous Caesar cipher where shift = 13

	encrypted := encrypt(original, shift)
	decrypted := decrypt(encrypted, shift)

	fmt.Println("=== Caesar Cipher ===")
	fmt.Printf("Shift value : %d\n", shift)
	fmt.Printf("Original    : %s\n", original)
	fmt.Printf("Encrypted   : %s\n", encrypted)
	fmt.Printf("Decrypted   : %s\n", decrypted)

	// Let's try a few more examples with different shifts
	fmt.Println()
	fmt.Println("--- More examples ---")

	messages := []struct {
		text  string
		shift int
	}{
		{"Secret Message", 3},
		{"RoboCode Rocks!", 7},
		{"Keep it safe", 21},
	}

	for _, m := range messages {
		enc := encrypt(m.text, m.shift)
		dec := decrypt(enc, m.shift)
		fmt.Printf("Original: %-20s  Shift: %2d  Encrypted: %-25s  Decrypted: %s\n",
			m.text, m.shift, enc, dec)
	}
}

