import (
	"fmt"
	"strings"
)

// Student holds a name and a list of test scores
type Student struct {
	Name   string
	Scores []float64
}

// Average calculates the mean score for a student.
// This is a METHOD — it belongs to the Student type.
func (s Student) Average() float64 {
	if len(s.Scores) == 0 {
		return 0
	}
	total := 0.0
	for _, score := range s.Scores {
		total += score
	}
	return total / float64(len(s.Scores))
}

// LetterGrade converts a numeric average into A/B/C/D/F
func (s Student) LetterGrade() string {
	avg := s.Average()
	switch {
	case avg >= 90:
		return "A"
	case avg >= 80:
		return "B"
	case avg >= 70:
		return "C"
	case avg >= 60:
		return "D"
	default:
		return "F"
	}
}

func main() {
	// Our class — hardcoded sample data
	class := []Student{
		{Name: "Alice", Scores: []float64{92, 88, 95, 91}},
		{Name: "Bob", Scores: []float64{74, 68, 79, 72}},
		{Name: "Charlie", Scores: []float64{85, 90, 88, 84}},
		{Name: "Diana", Scores: []float64{60, 55, 63, 58}},
		{Name: "Ethan", Scores: []float64{97, 99, 95, 100}},
	}

	fmt.Println("========== Student Gradebook ==========")
	fmt.Printf("%-10s  %-7s  %-6s  %s\n", "NAME", "AVERAGE", "GRADE", "SCORE BAR")
	fmt.Println(strings.Repeat("-", 50))

	classTotal := 0.0

	for _, student := range class {
		avg := student.Average()
		classTotal += avg

		// Build a bar: one block per 10 points (max 10 blocks for 100%)
		barLen := int(avg / 10)
		bar := strings.Repeat("█", barLen) + strings.Repeat("░", 10-barLen)

		fmt.Printf("%-10s  %6.1f%%  %-6s  %s\n",
			student.Name, avg, student.LetterGrade(), bar)
	}

	classAvg := classTotal / float64(len(class))
	fmt.Println(strings.Repeat("-", 50))
	fmt.Printf("%-10s  %6.1f%%\n", "CLASS AVG", classAvg)
	fmt.Println()
	fmt.Println("Grades: A=90+  B=80+  C=70+  D=60+  F=below 60")
}

use std::collections::HashMap;

fn main() {
    // Here's a sample sentence we want to analyse.
    // No user input needed — we bake the data right in!
    let text = "the quick brown fox jumps over the lazy dog \
                the fox was very quick and the dog was very lazy";

    // Split the sentence into individual words.
    // .split_whitespace() handles multiple spaces gracefully.
    let words: Vec<&str> = text.split_whitespace().collect();

    // A HashMap lets us store each word paired with a count.
    // Key = word (string slice), Value = how many times we saw it.
    let mut frequency: HashMap<&str, u32> = HashMap::new();

    for word in &words {
        // entry() is a handy Rust trick:
        // if the key exists, give us the value; otherwise insert 0 first.
        let count = frequency.entry(word).or_insert(0);
        *count += 1; // dereference the mutable reference to add 1
    }

    // Collect the entries into a Vec so we can sort them.
    let mut sorted: Vec<(&&str, &u32)> = frequency.iter().collect();

    // Sort by count descending, then alphabetically for ties.
    sorted.sort_by(|a, b| b.1.cmp(a.1).then(a.0.cmp(b.0)));

    println!("=== Word Frequency Counter ===");
    println!("{:<12} {}", "Word", "Count");
    println!("{}", "-".repeat(20));

    for (word, count) in &sorted {
        // :< means left-align; the number is the field width.
        println!("{:<12} {}", word, count);
    }

    println!();
    println!("Total words : {}", words.len());
    println!("Unique words: {}", frequency.len());
}

// Caesar cipher — shift every letter forward (encrypt) or backward (decrypt).
// Only A–Z and a–z are shifted; spaces, numbers, and punctuation stay unchanged.

/// Shifts a single ASCII letter by `shift` positions, wrapping around at Z/z.
/// Non-letter characters are returned unchanged.
fn shift_char(c: char, shift: u8) -> char {
    if c.is_ascii_uppercase() {
        // Treat A=0, B=1, … Z=25, then wrap with modulo 26.
        let offset = (c as u8 - b'A' + shift) % 26;
        (b'A' + offset) as char
    } else if c.is_ascii_lowercase() {
        let offset = (c as u8 - b'a' + shift) % 26;
        (b'a' + offset) as char
    } else {
        c // leave punctuation, digits, spaces alone
    }
}

/// Encrypts a message by shifting every letter forward.
fn encrypt(message: &str, shift: u8) -> String {
    message.chars().map(|c| shift_char(c, shift)).collect()
}

/// Decrypts by shifting backward (i.e. shifting forward by 26 - shift).
fn decrypt(ciphertext: &str, shift: u8) -> String {
    // Shifting forward by (26 - shift) is the same as shifting back by shift.
    let reverse_shift = 26 - (shift % 26);
    encrypt(ciphertext, reverse_shift)
}

fn main() {
    // --- Example 1: a classic short message ---
    let original = "Hello, World!";
    let shift = 3; // Caesar himself used a shift of 3

    let encrypted = encrypt(original, shift);
    let decrypted = decrypt(&encrypted, shift);

    println!("=== Caesar Cipher (shift = {}) ===", shift);
    println!("Original : {}", original);
    println!("Encrypted: {}", encrypted);
    println!("Decrypted: {}", decrypted);
    println!();

    // --- Example 2: a secret mission briefing ---
    let secret = "Meet me at the library after school";
    let key = 13; // ROT13 — a famous special case!

    let encoded = encrypt(secret, key);
    let decoded = decrypt(&encoded, key);

    println!("=== ROT13 (shift = {}) ===", key);
    println!("Original : {}", secret);
    println!("Encrypted: {}", encoded);
    println!("Decrypted: {}", decoded);
    println!();

    // Fun fact about ROT13
    println!("Fun fact: applying ROT13 twice gives back the original!");
    let double = encrypt(&encoded, key);
    println!("Double-encoded: {}", double);
}

// A simple gradebook — great for learning Rust structs, Vec, and methods!

/// One student with a name and a list of test scores.
struct Student {
    name: String,
    scores: Vec<f64>,
}

impl Student {
    /// Creates a new Student. `&str` is converted to an owned `String`.
    fn new(name: &str, scores: Vec<f64>) -> Student {
        Student {
            name: name.to_string(),
            scores,
        }
    }

    /// Calculates the average of all scores.
    /// Returns 0.0 if the student has no scores yet.
    fn average(&self) -> f64 {
        if self.scores.is_empty() {
            return 0.0;
        }
        let total: f64 = self.scores.iter().sum();
        total / self.scores.len() as f64
    }

    /// Converts a numeric average into a letter grade.
    fn letter_grade(&self) -> &str {
        match self.average() as u32 {
            90..=100 => "A",
            80..=89  => "B",
            70..=79  => "C",
            60..=69  => "D",
            _        => "F",
        }
    }
}

fn main() {
    // Build our class roster with hardcoded sample scores.
    let students = vec![
        Student::new("Alice",   vec![92.0, 88.0, 95.0, 91.0]),
        Student::new("Bob",     vec![74.0, 69.0, 80.0, 77.0]),
        Student::new("Chioma",  vec![85.0, 90.0, 88.0, 93.0]),
        Student::new("David",   vec![60.0, 55.0, 62.0, 58.0]),
        Student::new("Emeka",   vec![98.0, 100.0, 97.0, 99.0]),
    ];

    // Print the report card table.
    println!("=== Class Gradebook ===");
    println!("{:<10} {:>8}  {:>6}  {}", "Name", "Average", "Grade", "Scores");
    println!("{}", "-".repeat(50));

    for s in &students {
        // Format the scores as a comma-separated list.
        let score_list: Vec<String> = s.scores.iter().map(|sc| sc.to_string()).collect();
        println!(
            "{:<10} {:>8.2}  {:>6}  [{}]",
            s.name,
            s.average(),
            s.letter_grade(),
            score_list.join(", ")
        );
    }

    println!();

    // Find the top-performing student using max_by.
    // We use partial_cmp because f64 doesn't implement Ord (due to NaN).
    let top = students
        .iter()
        .max_by(|a, b| a.average().partial_cmp(&b.average()).unwrap());

    if let Some(star) = top {
        println!("Star student: {} with an average of {:.2}!", star.name, star.average());
    }

    // Calculate the class average.
    let class_avg: f64 = students.iter().map(|s| s.average()).sum::<f64>() / students.len() as f64;
    println!("Class average: {:.2}", class_avg);
}

#include <iostream>
#include <string>

// Shift every letter in the text by 'shift' positions.
// Letters wrap around: 'z' + 1 becomes 'a'.
// Non-letter characters (spaces, punctuation) are left unchanged.
std::string caesarEncode(const std::string& text, int shift) {
    std::string result = text;
    // Keep shift in the range 0-25
    shift = ((shift % 26) + 26) % 26;

    for (char& ch : result) {
        if (ch >= 'A' && ch <= 'Z') {
            // Uppercase letter
            ch = static_cast<char>('A' + (ch - 'A' + shift) % 26);
        } else if (ch >= 'a' && ch <= 'z') {
            // Lowercase letter
            ch = static_cast<char>('a' + (ch - 'a' + shift) % 26);
        }
        // Anything else stays the same
    }
    return result;
}

// Decoding is just encoding with the opposite shift
std::string caesarDecode(const std::string& text, int shift) {
    return caesarEncode(text, -shift);
}

int main() {
    std::string original = "Hello, World! Meet me at the clock tower.";
    int shift = 13; // ROT13 is a famous Caesar cipher with shift = 13

    std::string encoded = caesarEncode(original, shift);
    std::string decoded = caesarDecode(encoded, shift);

    std::cout << "=== Caesar Cipher (shift = " << shift << ") ===\n\n";
    std::cout << "Original : " << original << "\n";
    std::cout << "Encoded  : " << encoded  << "\n";
    std::cout << "Decoded  : " << decoded  << "\n";

    // Try a different message and shift
    std::string secret  = "Top secret: launch at dawn!";
    int shift2 = 7;
    std::string encoded2 = caesarEncode(secret, shift2);
    std::string decoded2 = caesarDecode(encoded2, shift2);

    std::cout << "\n=== Caesar Cipher (shift = " << shift2 << ") ===\n\n";
    std::cout << "Original : " << secret  << "\n";
    std::cout << "Encoded  : " << encoded2 << "\n";
    std::cout << "Decoded  : " << decoded2 << "\n";

    std::cout << "\nFun fact: ROT13 (shift 13) is self-inverse —\n";
    std::cout << "apply it twice and you get the original back!\n";

    return 0;
}

#include <iostream>
#include <vector>
#include <iomanip>

// The Sieve of Eratosthenes works like this:
// 1. Assume every number >= 2 is prime.
// 2. Starting from 2, mark all its multiples as NOT prime.
// 3. Move to the next unmarked number and repeat.
// 4. Whatever remains unmarked is prime!
std::vector<int> sieve(int limit) {
    // isPrime[i] = true means we still think i might be prime
    std::vector<bool> isPrime(limit + 1, true);
    isPrime[0] = false; // 0 is not prime
    isPrime[1] = false; // 1 is not prime by definition

    for (int p = 2; p * p <= limit; ++p) {
        if (isPrime[p]) {
            // Mark every multiple of p (starting at p*p) as composite
            for (int multiple = p * p; multiple <= limit; multiple += p) {
                isPrime[multiple] = false;
            }
        }
    }

    // Collect all surviving primes into a list
    std::vector<int> primes;
    for (int i = 2; i <= limit; ++i) {
        if (isPrime[i]) {
            primes.push_back(i);
        }
    }
    return primes;
}

int main() {
    const int LIMIT = 100;
    std::vector<int> primes = sieve(LIMIT);

    std::cout << "=== Sieve of Eratosthenes ===\n";
    std::cout << "Finding all prime numbers up to " << LIMIT << ":\n\n";

    // Print primes in a neat grid (10 per row)
    int count = 0;
    for (int p : primes) {
        std::cout << std::setw(4) << p;
        ++count;
        if (count % 10 == 0) {
            std::cout << "\n";
        }
    }
    std::cout << "\n";

    std::cout << "\nTotal primes found: " << primes.size() << "\n";
    std::cout << "Smallest prime : " << primes.front() << "\n";
    std::cout << "Largest prime  : " << primes.back()  << "\n";

    // Count twin primes (pairs that differ by 2, e.g. 11 and 13)
    int twinCount = 0;
    std::cout << "\nTwin prime pairs (differ by 2):\n";
    for (int i = 0; i + 1 < static_cast<int>(primes.size()); ++i) {
        if (primes[i + 1] - primes[i] == 2) {
            std::cout << "  (" << primes[i] << ", " << primes[i + 1] << ")\n";
            ++twinCount;
        }
    }
    std::cout << "Total twin prime pairs: " << twinCount << "\n";

    return 0;
}

#include <iostream>
#include <map>
#include <string>
#include <sstream>
#include <algorithm>
#include <cctype>

// Strip punctuation from both ends of a word and convert to lowercase.
// This means "Hello," and "hello" are counted as the same word.
std::string cleanWord(const std::string& raw) {
    std::string w = raw;

    // Remove leading non-alpha characters
    while (!w.empty() && !std::isalpha(static_cast<unsigned char>(w.front()))) {
        w.erase(w.begin());
    }
    // Remove trailing non-alpha characters
    while (!w.empty() && !std::isalpha(static_cast<unsigned char>(w.back()))) {
        w.pop_back();
    }
    // Lowercase everything
    for (char& c : w) {
        c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
    }
    return w;
}

int main() {
    // Sample text — try changing this to anything you like!
    std::string text =
        "To be or not to be, that is the question. "
        "Whether tis nobler in the mind to suffer "
        "the slings and arrows of outrageous fortune, "
        "or to take arms against a sea of troubles.";

    // Use a map to count frequencies — map keeps keys sorted alphabetically
    std::map<std::string, int> freq;

    std::istringstream stream(text);
    std::string token;
    while (stream >> token) {
        std::string word = cleanWord(token);
        if (!word.empty()) {
            freq[word]++; // Increment count (starts at 0 automatically)
        }
    }

    // Find the highest frequency so we can scale the bars
    int maxFreq = 0;
    for (const auto& [word, count] : freq) {
        maxFreq = std::max(maxFreq, count);
    }

    const int BAR_WIDTH = 30; // Maximum bar length in characters

    std::cout << "=== Word Frequency Chart ===\n";
    std::cout << "Text: \"" << text.substr(0, 50) << "...\"\n\n";
    std::cout << std::string(50, '-') << "\n";

    for (const auto& [word, count] : freq) {
        // Scale bar length proportionally to the max frequency
        int barLen = (count * BAR_WIDTH) / maxFreq;
        std::string bar(barLen, '#');

        // Print: word (padded) | bar  count
        // setw won't work easily here, so pad manually
        std::string padded = word + std::string(12 - std::min(12, static_cast<int>(word.size())), ' ');
        std::cout << padded << "| " << bar;

        // Add count label at the end of the bar
        std::cout << " " << count << "\n";
    }

    std::cout << std::string(50, '-') << "\n";
    std::cout << "Unique words : " << freq.size() << "\n";

    // Find the most common word
    auto mostCommon = std::max_element(
        freq.begin(), freq.end(),
        [](const auto& a, const auto& b) { return a.second < b.second; }
    );
    std::cout << "Most common  : \"" << mostCommon->first
              << "\" (" << mostCommon->second << " times)\n";

    return 0;
}

using System;

// Caesar Cipher
// Encrypts and decrypts text by shifting each letter by a set amount.
// Example: shift 3 turns 'A' into 'D', 'B' into 'E', and so on.

class Program
{
    // Shift every letter in the message by 'shift' positions.
    // Letters wrap around: Z + 1 becomes A.
    // Non-letter characters (spaces, punctuation) are left unchanged.
    static string ApplyCipher(string message, int shift)
    {
        // Keep the shift in the range 0-25 using modulo.
        shift = ((shift % 26) + 26) % 26;

        char[] result = new char[message.Length];

        for (int i = 0; i < message.Length; i++)
        {
            char c = message[i];

            if (char.IsLetter(c))
            {
                // Work out the base: 'A' for uppercase, 'a' for lowercase.
                char baseChar = char.IsUpper(c) ? 'A' : 'a';

                // Shift the letter and wrap around using modulo 26.
                result[i] = (char)(baseChar + (c - baseChar + shift) % 26);
            }
            else
            {
                // Not a letter — keep it as-is.
                result[i] = c;
            }
        }

        return new string(result);
    }

    static void Main()
    {
        Console.WriteLine("=== Caesar Cipher ===");
        Console.WriteLine();

        string original = "Hello, World! Meet me at the castle.";
        int shift = 13; // ROT13 is a popular shift-13 cipher

        Console.WriteLine("Original message : " + original);
        Console.WriteLine("Shift amount     : " + shift);
        Console.WriteLine();

        // Encrypt the message
        string encrypted = ApplyCipher(original, shift);
        Console.WriteLine("Encrypted        : " + encrypted);

        // Decrypt by shifting in the opposite direction (or by 26 - shift)
        string decrypted = ApplyCipher(encrypted, 26 - shift);
        Console.WriteLine("Decrypted        : " + decrypted);

        Console.WriteLine();
        Console.WriteLine("--- Trying a few different shifts ---");

        string secret = "Robots are cool!";
        Console.WriteLine("Message: " + secret);

        for (int s = 1; s <= 5; s++)
        {
            string enc = ApplyCipher(secret, s);
            Console.WriteLine("  Shift " + s + ": " + enc);
        }

        Console.WriteLine();
        Console.WriteLine("Fun fact: Shift 13 is called ROT13 and is its own inverse!");
        Console.WriteLine("Encrypting twice with shift 13 gives back the original.");
    }
}

using System;
using System.Collections.Generic;

// Word Frequency Counter
// Splits a block of text into words, counts how many times each word
// appears, then prints a leaderboard from most to least frequent.

class Program
{
    static void Main()
    {
        Console.WriteLine("=== Word Frequency Counter ===");
        Console.WriteLine();

        // Sample text — feel free to swap this for any passage you like!
        string text =
            "To be or not to be that is the question " +
            "Whether tis nobler in the mind to suffer " +
            "the slings and arrows of outrageous fortune " +
            "or to take arms against a sea of troubles " +
            "and by opposing end them to die to sleep " +
            "no more and by a sleep to say we end " +
            "the heartache and the thousand natural shocks " +
            "that flesh is heir to";

        Console.WriteLine("Analysing this text:");
        Console.WriteLine(text);
        Console.WriteLine();

        // Step 1: Split the text into individual words.
        // StringSplitOptions.RemoveEmptyEntries drops any accidental extra spaces.
        string[] words = text.Split(
            new char[] { ' ', ',', '.', '!', '?', ';', ':', '-' },
            StringSplitOptions.RemoveEmptyEntries
        );

        // Step 2: Count each word using a Dictionary.
        // The key is the lowercase word; the value is its count.
        Dictionary<string, int> frequency = new Dictionary<string, int>();

        foreach (string word in words)
        {
            string lower = word.ToLower();

            if (frequency.ContainsKey(lower))
            {
                // Word already seen — increment the count.
                frequency[lower]++;
            }
            else
            {
                // First time we've seen this word — start at 1.
                frequency[lower] = 1;
            }
        }

        Console.WriteLine("Total words      : " + words.Length);
        Console.WriteLine("Unique words     : " + frequency.Count);
        Console.WriteLine();

        // Step 3: Sort entries by count descending, then alphabetically.
        // We build a list of pairs so we can sort them.
        List<KeyValuePair<string, int>> sorted =
            new List<KeyValuePair<string, int>>(frequency);

        sorted.Sort(delegate(KeyValuePair<string, int> a, KeyValuePair<string, int> b)
        {
            // Higher count first; break ties alphabetically.
            int cmp = b.Value.CompareTo(a.Value);
            if (cmp != 0) return cmp;
            return string.Compare(a.Key, b.Key, StringComparison.Ordinal);
        });

        // Step 4: Print the leaderboard (top 10).
        Console.WriteLine("--- Top 10 Most Frequent Words ---");
        Console.WriteLine("Rank  Word                Count  Bar");
        Console.WriteLine(new string('-', 45));

        int maxToShow = Math.Min(10, sorted.Count);
        for (int i = 0; i < maxToShow; i++)
        {
            string w = sorted[i].Key;
            int count = sorted[i].Value;

            // Build a simple bar made of # characters.
            string bar = new string('#', count * 2);

            // Pad the rank and word so columns line up neatly.
            Console.WriteLine(
                (i + 1).ToString().PadRight(6) +
                w.PadRight(20) +
                count.ToString().PadRight(7) +
                bar
            );
        }

        Console.WriteLine();
        Console.WriteLine("Tip: Try swapping the text for your favourite song lyrics!");
    }
}

using System;
using System.Collections.Generic;

// Bank Account Simulator
// Demonstrates object-oriented programming (OOP): we define a BankAccount
// class with methods for depositing, withdrawing, and viewing history.

// A single bank account — stores the balance and all past transactions.
class BankAccount
{
    // Properties: the owner's name and their current balance.
    public string OwnerName { get; private set; }
    public decimal Balance   { get; private set; }

    // Keep a list of every transaction as a human-readable string.
    private List<string> history = new List<string>();

    // Constructor — runs when we create a new BankAccount object.
    public BankAccount(string ownerName, decimal openingBalance)
    {
        OwnerName = ownerName;
        Balance   = openingBalance;

        // Record the opening deposit in the history log.
        history.Add("Account opened with " + FormatAmount(openingBalance));
    }

    // Deposit money into the account.
    public void Deposit(decimal amount, string note)
    {
        if (amount <= 0)
        {
            Console.WriteLine("  [!] Deposit amount must be greater than zero.");
            return;
        }

        Balance += amount;
        history.Add("Deposit   +" + FormatAmount(amount).PadRight(10) +
                    " | " + note + " | Balance: " + FormatAmount(Balance));
    }

    // Withdraw money from the account.
    public void Withdraw(decimal amount, string note)
    {
        if (amount <= 0)
        {
            Console.WriteLine("  [!] Withdrawal amount must be greater than zero.");
            return;
        }

        if (amount > Balance)
        {
            // Not enough funds — reject the withdrawal.
            Console.WriteLine("  [!] Insufficient funds! Balance is only " +
                              FormatAmount(Balance) + ".");
            return;
        }

        Balance -= amount;
        history.Add("Withdraw  -" + FormatAmount(amount).PadRight(10) +
                    " | " + note + " | Balance: " + FormatAmount(Balance));
    }

    // Print the full transaction history to the console.
    public void PrintStatement()
    {
        Console.WriteLine("  Account holder : " + OwnerName);
        Console.WriteLine("  Current balance: " + FormatAmount(Balance));
        Console.WriteLine("  " + new string('-', 60));

        foreach (string entry in history)
        {
            Console.WriteLine("  " + entry);
        }
    }

    // Helper: format a decimal as a currency string like $1,234.56
    private string FormatAmount(decimal amount)
    {
        return "$" + amount.ToString("N2");
    }
}

class Program
{
    static void Main()
    {
        Console.WriteLine("=== Bank Account Simulator ===");
        Console.WriteLine();

        // Create two separate accounts — each is its own object.
        BankAccount alice = new BankAccount("Alice", 500.00m);
        BankAccount bob   = new BankAccount("Bob",   150.00m);

        // Perform some transactions on Alice's account.
        Console.WriteLine("--- Alice's transactions ---");
        alice.Deposit(200.00m,  "Birthday gift");
        alice.Deposit(1000.00m, "Monthly salary");
        alice.Withdraw(75.50m,  "Grocery shopping");
        alice.Withdraw(300.00m, "Laptop purchase");
        alice.Withdraw(2000.00m, "Trying to overspend!"); // Should fail
        Console.WriteLine();

        // Perform some transactions on Bob's account.
        Console.WriteLine("--- Bob's transactions ---");
        bob.Deposit(50.00m,  "Sold old games");
        bob.Withdraw(30.00m, "Bus pass");
        bob.Withdraw(200.00m, "Can't afford this!"); // Should fail
        Console.WriteLine();

        // Print bank statements.
        Console.WriteLine("=============================");
        Console.WriteLine(" ALICE'S BANK STATEMENT");
        Console.WriteLine("=============================");
        alice.PrintStatement();

        Console.WriteLine();
        Console.WriteLine("=============================");
        Console.WriteLine(" BOB'S BANK STATEMENT");
        Console.WriteLine("=============================");
        bob.PrintStatement();

        Console.WriteLine();
        Console.WriteLine("Great job! You just used classes, objects, and methods.");
    }
}
